svg.script:
(function() {
  'use strict';

  var svgRoot = document.getElementById('a12p15-svg');
  if (!svgRoot) return;

  var infoData = {
    'puborretal': {
      title: 'PUBO + RRETAL = Púbis → Reto (Alça em U)',
      color: 'var(--a12p15-puborretal)',
      route: 'ORIGEM: Face posterior do Púbis  →  DESTINO: Contorna a junção anorretal posterior e retorna ao Púbis.',
      effect: 'AÇÃO & CLÍNICA: Traciona o reto anterior/superiormente, criando o Ângulo Anorretal (~89° em repouso vs ~74° em contração). Crucial para a continência fecal.',
      angleText: '74° Contração'
    },
    'pubococcigeo': {
      title: 'PUBO + COCCÍGEO = Púbis → Cóccix',
      color: 'var(--a12p15-pubococcigeo)',
      route: 'ORIGEM: Face posterior do Púbis (lateral ao puborretal)  →  DESTINO: Cóccix e Rafe Anococcígea.',
      effect: 'AÇÃO & CLÍNICA: Eleva o assoalho pélvico e sustenta as vísceras pélvicas contra a gravidade e pressão intra-abdominal.',
      angleText: '89° Repouso'
    },
    'iliococcigeo': {
      title: 'ILIO + COCCÍGEO = Arco Tendíneo (Ílio) → Cóccix',
      color: 'var(--a12p15-iliococcigeo)',
      route: 'ORIGEM: Arco Tendíneo do M. Levantador do Ânus (ATFP) na parede lateral  →  DESTINO: Cóccix.',
      effect: 'AÇÃO & CLÍNICA: Forma a porção posterior e lateral do diafragma pélvico ("cama rígida de sustentação").',
      angleText: '89° Repouso'
    },
    'coccigeo': {
      title: 'ISQUIO + COCCÍGEO = Espinha Isquiática → Cóccix',
      color: 'var(--a12p15-coccigeo)',
      route: 'ORIGEM: Espinha Isquiática e Ligamento Sacroespinal  →  DESTINO: Margem lateral do Sacro e Cóccix.',
      effect: 'AÇÃO & CLÍNICA: Músculo posterior (independente do Levantador do Ânus). Traciona o cóccix anterior/medialmente pós-defecação/parto.',
      angleText: '89° Repouso'
    },
    'none': {
      title: 'Assoalho Pélvico Completo (Diafragma Pélvico)',
      color: 'var(--a12p15-tinta)',
      route: 'Nomenclatura = Endereço: A primeira metade indica a ORIGEM pélvica; a segunda indica o DESTINO de inserção.',
      effect: 'Clique ou navegue pelos feixes para rastrear os trajetos e observar o efeito da alça do puborretal no ângulo anorretal.',
      angleText: '89° Repouso'
    }
  };

  function setActiveFeixe(feixeKey) {
    if (!infoData[feixeKey]) feixeKey = 'none';

    svgRoot.setAttribute('data-active-feixe', feixeKey);

    // Update Reading Info Panel
    var data = infoData[feixeKey];
    var titleElem = document.getElementById('a12p15-info-title');
    var routeElem = document.getElementById('a12p15-info-route');
    var effectElem = document.getElementById('a12p15-info-effect');
    var angleValElem = document.getElementById('a12p15-angle-val');

    if (titleElem) {
      titleElem.textContent = data.title;
      titleElem.style.fill = data.color;
    }
    if (routeElem) routeElem.textContent = data.route;
    if (effectElem) effectElem.textContent = data.effect;
    if (angleValElem) angleValElem.textContent = data.angleText;

    // Update ARIA States on Buttons
    var buttons = svgRoot.querySelectorAll('.a12p15-btn');
    buttons.forEach(function(btn) {
      var key = btn.getAttribute('data-feixe');
      if (key === feixeKey) {
        btn.setAttribute('aria-selected', 'true');
      } else {
        btn.setAttribute('aria-selected', 'false');
      }
    });
  }

  // Event Listeners for Muscle Groups & Buttons
  var interactiveElems = svgRoot.querySelectorAll('[data-feixe]');
  interactiveElems.forEach(function(elem) {
    function trigger() {
      var feixeKey = elem.getAttribute('data-feixe');
      var current = svgRoot.getAttribute('data-active-feixe');
      if (current === feixeKey && elem.classList.contains('a12p15-muscle-group')) {
        setActiveFeixe('none');
      } else {
        setActiveFeixe(feixeKey);
      }
    }

    elem.addEventListener('click', function(e) {
      e.stopPropagation();
      trigger();
    });

    elem.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        trigger();
      }
    });
  });

  // Background click resets to full view
  svgRoot.addEventListener('click', function(e) {
    if (e.target === svgRoot || e.target.classList.contains('a12p15-panel')) {
      setActiveFeixe('none');
    }
  });
})();
